script:
test("partial hour rounds up to the next whole hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 10:01" }), { status: "ok", elapsedMinutes: 121, roundedHours: 3, billableHours: 3, flags: [] });
});

test("real time across spring forward keeps exact hours unchanged", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-03-07 22:00", discharge: "2026-03-08 22:00" }), { status: "ok", elapsedMinutes: 1380, roundedHours: 23, billableHours: 23, flags: [] });
});

test("real time across fall back counts the repeated hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-10-31 22:00", discharge: "2026-11-01 22:00" }), { status: "ok", elapsedMinutes: 1500, roundedHours: 25, billableHours: 25, flags: [] });
});

test("a stay longer than 48 hours is billed as 48", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-13 08:00" }), { status: "ok", elapsedMinutes: 4320, roundedHours: 72, billableHours: 48, flags: [] });
});

test("zero elapsed time is valid and stays exact", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-01 00:00", discharge: "2026-01-01 00:00" }), { status: "ok", elapsedMinutes: 0, roundedHours: 0, billableHours: 0, flags: [] });
});

test("an exact hour outside the repeated hour stays one hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-11-01 02:00", discharge: "2026-11-01 03:00" }), { status: "ok", elapsedMinutes: 60, roundedHours: 1, billableHours: 1, flags: [] });
});

test("one minute on a leap day rounds up to one hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2024-02-29 08:00", discharge: "2024-02-29 08:01" }), { status: "ok", elapsedMinutes: 1, roundedHours: 1, billableHours: 1, flags: [] });
});

test("twenty nine minutes rounds up to one hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-31 08:00", discharge: "2026-01-31 08:29" }), { status: "ok", elapsedMinutes: 29, roundedHours: 1, billableHours: 1, flags: [] });
});

test("thirty minutes across the new year rounds up to one hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2025-12-31 23:40", discharge: "2026-01-01 00:10" }), { status: "ok", elapsedMinutes: 30, roundedHours: 1, billableHours: 1, flags: [] });
});

test("thirty one minutes before the spring forward gap rounds up to one hour", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-03-08 01:28", discharge: "2026-03-08 01:59" }), { status: "ok", elapsedMinutes: 31, roundedHours: 1, billableHours: 1, flags: [] });
});

test("forty seven hours stays one hour below the cap", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-31 10:00", discharge: "2026-02-02 09:00" }), { status: "ok", elapsedMinutes: 2820, roundedHours: 47, billableHours: 47, flags: [] });
});

test("exactly 48 hours across a leap day is billed as 48", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2024-02-28 08:00", discharge: "2024-03-01 08:00" }), { status: "ok", elapsedMinutes: 2880, roundedHours: 48, billableHours: 48, flags: [] });
});

test("forty nine hours is capped at 48", function () {
  assert.deepEqual(code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-12 09:00" }), { status: "ok", elapsedMinutes: 2940, roundedHours: 49, billableHours: 48, flags: [] });
});

test("an ambiguous admission time is flagged and no hours are computed", function () {
  var result = code.billableObservationHours({ admission: "2026-11-01 01:30", discharge: "2026-11-01 03:00" });
  assert.equal(result.status, "ambiguous");
  assert.equal(result.elapsedMinutes, null);
  assert.equal(result.roundedHours, null);
  assert.equal(result.billableHours, null);
  assert.equal(result.flags.length, 1);
  assert.match(result.flags[0], /admission/);
});

test("a nonexistent discharge time is flagged and no hours are computed", function () {
  var result = code.billableObservationHours({ admission: "2026-03-08 01:00", discharge: "2026-03-08 02:30" });
  assert.equal(result.status, "nonexistent");
  assert.equal(result.elapsedMinutes, null);
  assert.equal(result.roundedHours, null);
  assert.equal(result.billableHours, null);
  assert.equal(result.flags.length, 1);
  assert.match(result.flags[0], /discharge/);
});

test("a discharge one minute earlier than admission is invalid", function () {
  var result = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 07:59" });
  assert.equal(result.status, "invalid");
  assert.equal(result.elapsedMinutes, null);
  assert.equal(result.roundedHours, null);
  assert.equal(result.billableHours, null);
  assert.equal(result.flags.length, 1);
  assert.match(result.flags[0], /discharge/);
});
